/** Clear messages also cover HTML errors generated by an upstream proxy. */
export async function responseError(response: Response, fallback: string): Promise<string> {
  if (response.status === 429) {
    return "Too many requests. Please wait a moment and try again.";
  }
  if (response.status === 503) {
    return "The server is busy processing another model. Please try again in a few seconds.";
  }
  if (response.status === 504) {
    return "Processing took too long. Please try again.";
  }
  try {
    const data = await response.json();
    return typeof data.detail === "string" ? data.detail : fallback;
  } catch {
    return fallback;
  }
}
